/* COMMON. A functional research-community prototype; intentionally no investment execution. */
'use strict';
const app = document.getElementById('app');
const toastEl = document.getElementById('toast');
const state = { user: null, view: 'overview', communities: [], proposals: [], watches: [], activity: [], selected: null, category: 'ALL', authMode: 'register', publicPreview: true, modal: null, lesson: null, fundLab: null, fundCommunity: null, featurePreview: 'brokerage', secSymbol: 'TSLA', secData: null, pendingInvite: new URLSearchParams(location.search).get('invite') };
