const icon = (name, size=18) => `<svg class="icon" viewBox="0 0 24 24" width="${size}" height="${size}" aria-hidden="true">${icons[name] || icons.layers}</svg>`;
const esc = v => String(v ?? '').replace(/[&<>"']/g, m=>({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[m]));
const truncate = (v,n=130) => v.length>n?v.slice(0,n)+'…':v;
const when = iso => new Date(iso).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const categoryName = type => ({PUBLIC_EQUITY:'Public markets',HOUSING:'Housing',BUSINESS:'Local business'})[type] || type;
const labelTopic = v => ({RESEARCH:'Research',EDUCATION:'Education',GOVERNANCE:'Governance',OWNERSHIP:'Ownership'})[v] || v;
const toast = (message, bad=false) => {toastEl.textContent=message;toastEl.className='toast show'+(bad?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>toastEl.className='toast',3500)};

// GitHub Pages: all actions run in a local educational browser sandbox.
async function api(path, options={}) { return window.commonDemoApi(path, options); }
async function loadData(){
  const [communities, proposals, watches, activity]=await Promise.all([api('/communities'),api('/proposals'),api('/watchlist'),api('/activity')]);
  state.communities=communities.items;state.proposals=proposals.items;state.watches=watches.symbols;state.activity=activity.items;
}
async function applyPendingInvite(){
  if(!state.pendingInvite || !state.user)return;
  const code=state.pendingInvite;state.pendingInvite=null;
  history.replaceState(null,'',location.pathname);
  try{const data=await api('/invites/'+encodeURIComponent(code)+'/accept',{method:'POST'});await loadData();state.selected=data.community;state.view='community';toast('Invitation accepted. You joined the community.')}
  catch(err){toast(err.message,true)}
}
async function initialize(){
  try{const config=await api('/config');state.publicPreview=Boolean(config.public_preview_only);document.body.classList.toggle('preview-mode',state.publicPreview)}catch{}
  try{const info=await api('/me');state.user=info.user;await loadData();await applyPendingInvite();render()}
  catch{state.user=null;render()}
}

function logo(){return `<div class="logo"><div class="logo-icon">C<span>•</span></div>COMMON</div>`}
function authScreen(){
  const register=state.authMode==='register';
  return `<div class="auth-shell"><section class="auth-hero">${logo()}<div><div class="overline" style="color:var(--lime)">The ownership network</div><h1>Your future.<br/><em>Our power.</em></h1><p class="subtitle">Wealth-building, shareholder education, and community ownership—made understandable for everyone.</p></div><p class="auth-micro">Own your decisions. Learn with others. Build a more accessible financial future.<br/>Education and community tools only. No trading or fund pooling in this prototype.</p></section>
  <section class="auth-side"><div class="auth-panel"><div class="overline">Start here</div><h2>The table has room for everyone.</h2><p>Join a community that believes understanding and ownership should never be reserved for the few.</p>
  <button class="btn btn-primary" data-action="demo">${icon('arrow')} Explore interactive demo as Joe</button>
  ${state.publicPreview ? '<div class="notice"><strong>Public demo only.</strong> No signups, financial accounts or permanent data. Your demo activity may reset when the free server restarts.</div>' : ''}
  <div class="auth-sep">OR CREATE AN ACCOUNT</div>
  <div class="auth-tabs"><button class="${register?'selected':''}" data-action="auth-mode" data-mode="register">Sign up</button><button class="${!register?'selected':''}" data-action="auth-mode" data-mode="login">Sign in</button></div>
  <form id="auth-form">${register?`<div class="field"><label for="auth-name">Your name</label><input id="auth-name" name="name" placeholder="e.g. Joe Smith" minlength="2" maxlength="80" autocomplete="name" required /></div>`:''}
  <div class="field"><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" placeholder="you@example.com" autocomplete="email" required /></div>
  <div class="field"><label for="auth-password">Password ${register?'(at least 12 characters)':''}</label><input id="auth-password" name="password" type="password" minlength="${register?12:1}" autocomplete="${register?'new-password':'current-password'}" required /></div>
  <button class="btn btn-dark" type="submit">${register?'Create account':'Sign in'} ${icon('arrow')}</button></form><p class="auth-note">Prototype: real investments, brokerage integrations, member funds, verified holdings, and formal proxy voting are not enabled. Never enter bank credentials or financial account numbers here.</p></div></section></div>`;
}
const menu=[['overview','home','Overview'],['communities','users','Communities'],['discussions','vote','Discussions'],['watchlist','chart','My watchlist'],['fundlab','wallet','Fund builder'],['ownership','building','Ownership demos'],['learn','book','Learn']];
function navButton([key,ic,title],mobile=false){return `<button type="button" class="${mobile?'':'side-link '}${state.view===key?'selected':''}" data-action="nav" data-view="${key}">${mobile?'':icon(ic)}${title}</button>`}
function shell(content){return `<div class="mobile-top"><div>${logo()}</div><div class="mobile-nav">${menu.map(m=>navButton(m,true)).join('')}</div></div><div class="shell"><aside class="sidebar">${logo()}<div class="side-section">YOUR SPACE</div>${menu.map(m=>navButton(m)).join('')}<div class="sidebar-bottom"><div class="badge badge-dark">${icon('shield',13)} Build responsibly</div><h4>Knowledge comes first.</h4><p>No pressure, no hidden trades, no promises of returns.</p><button class="btn btn-lime" data-action="nav" data-view="learn">Start learning ${icon('arrow',14)}</button></div><div class="sidebar-profile"><div class="avatar">${esc(state.user.name.charAt(0).toUpperCase())}</div><div class="grow"><strong>${esc(state.user.name)}</strong><small>${state.user.demo?'Demo member':'Member account'}</small></div><button class="side-link logout" title="Sign out" aria-label="Sign out" data-action="logout">${icon('logout')}</button></div></aside><div class="main"><header class="topbar"><div class="breadcrumbs">COMMON <span style="color:#a2b1a5">/</span> <strong>${esc(menu.find(m=>m[0]===state.view)?.[2] || 'Community')}</strong></div><div class="right-top"><span class="badge badge-gray">${icon('shield',13)} Research platform</span><span class="badge">${icon('eye',13)} ${state.user.demo?'Demo':'Member'}</span></div></header><main class="page">${content}<div class="footer-disclaimer">COMMON is a software prototype for research, education, and community discussion. Sample communities and proposals are fictional examples. Community polls are never binding shareholder proxy votes. No investing, deposits, execution, custody, real-estate offerings, or advice are provided. Example actions are stored only in your browser session and are not shared.</div></main></div></div>`}
function metric(title,value,sub,ic){return `<div class="card metric"><div class="metric-head"><span class="label">${title}</span><div class="metric-icon">${icon(ic)}</div></div><div class="figure">${value}</div><div class="sub">${sub}</div></div>`}
function communityCard(c){return `<article class="card community-card"><div class="toprow"><div class="community-icon">${icon(c.icon,23)}</div>${c.sample?'<span class="badge badge-gray">Sample group</span>':c.visibility==='PRIVATE'?'<span class="badge badge-cream">Private group</span>':'<span class="badge">Member-created</span>'}</div><div class="label">${categoryName(c.category)}${c.symbol?' · '+esc(c.symbol):''}</div><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="community-footer"><span>${c.joined?'<span class="dot"></span> You joined':'Open discussion community'}</span><button data-action="open-community" data-slug="${esc(c.slug)}">Explore ${icon('arrow',13)}</button></div></article>`}
function proposalRow(p){return `<div class="proposal-row"><div class="proposal-topic">${icon(p.topic==='GOVERNANCE'?'vote':p.topic==='OWNERSHIP'?'building':'book')}</div><div class="grow"><div class="label">${esc(p.community_name)} · ${labelTopic(p.topic)}</div><h3>${esc(p.title)}</h3><p>${esc(p.author)} · ${when(p.created_at)} ${p.sample?' · Example':''}</p></div><div class="right"><button class="btn btn-quiet btn-mini" data-action="open-discussions">Discuss ${icon('arrow',13)}</button></div></div>`}
function overview(){
 const joined=state.communities.filter(c=>c.joined).length;
 return `<div class="page-heading"><div><div class="eyebrow">Your home base</div><h1>Good to see you, ${esc(state.user.name.split(' ')[0])}.</h1><p>Invest in your knowledge. Organize your ideas. Own your decisions.</p></div><button class="btn btn-quiet" data-action="nav" data-view="fundlab">${icon('wallet')} Open fund lab</button></div>
 <div class="hero-banner"><div class="eyebrow">Belong to something bigger</div><h2>Ownership isn't just for people with millions.</h2><p>Connect with everyday people, research public companies, and explore ways communities can build lasting wealth.</p><div class="hero-buttons"><button class="btn btn-lime" data-action="nav" data-view="communities">Explore communities ${icon('arrow',16)}</button><button class="btn btn-quiet" data-action="nav" data-view="fundlab">Build a sample fund ${icon('wallet',16)}</button></div></div>
 <div class="metric-grid">${metric('Communities joined',joined,'Research groups you follow','users')}${metric('Saved symbols',state.watches.length,'Tracking only; no holdings','eye')}${metric('Community discussions',state.proposals.length,'Includes illustrative examples','vote')}${metric('Real trades','$0','Trading is not enabled','shield')}</div>
 <div class="two-column"><div><div class="section-bar"><div><h2 class="section-title">Explore communities</h2><p class="section-subtitle">Find people curious about the same things.</p></div><button class="text-link" data-action="nav" data-view="communities">See all ${icon('arrow')}</button></div><div class="community-grid">${state.communities.slice(0,4).map(communityCard).join('')}</div></div><div><div class="section-bar"><div><h2 class="section-title">Your next move</h2><p class="section-subtitle">Start with understanding.</p></div></div><div class="research-card"><div class="research-spot"><div class="label">Ownership 101</div><h3>Learn what you really own.</h3><p>Shares, votes, earnings and risk—without the jargon.</p><button class="btn btn-primary btn-mini" data-action="nav" data-view="learn" style="margin-top:18px">Start here ${icon('arrow',13)}</button></div><div class="card research-mini"><div class="label">Product roadmap</div><h3>Investing with control, not hype.</h3><p>Future brokerage and ownership features will only launch with compliant partners and investor safeguards.</p></div></div></div></div>
 <div style="margin-top:29px"><div class="section-bar"><div><h2 class="section-title">Ideas being discussed</h2><p class="section-subtitle">These are community polls, not shareholder votes or trade orders.</p></div><button class="text-link" data-action="nav" data-view="discussions">All discussions ${icon('arrow')}</button></div><div class="card">${state.proposals.slice(0,4).map(proposalRow).join('')}</div></div>`;
}
function communityList(){const filtered=state.communities.filter(c=>state.category==='ALL'||c.category===state.category);return `<div class="page-heading"><div><div class="eyebrow">Find your people</div><h1>Communities</h1><p>Explore research groups and learn from others. Everyone makes their own financial decisions.</p></div><button class="btn btn-primary" data-action="create-group">${icon('plus')} Create a group</button></div><div class="notice">${icon('info')}<span>Membership is free in this demo. It does not establish a pooled fund, investment partnership, collective share ownership, or verified shareholder position.</span></div><div class="filters">${[['ALL','All communities'],['PUBLIC_EQUITY','Public markets'],['HOUSING','Housing'],['BUSINESS','Local businesses']].map(([key,label])=>`<button class="pill ${state.category===key?'active':''}" data-action="category" data-category="${key}">${label}</button>`).join('')}</div><div class="community-grid">${filtered.map(communityCard).join('')}</div>`}
function discussionCard(p){const sum=Object.values(p.poll_counts).reduce((a,b)=>a+b,0);const c=state.communities.find(c=>c.slug===p.community_slug);return `<article class="card discussion-card"><div class="discussion-meta"><span class="badge">${labelTopic(p.topic)}</span><span>${esc(p.community_name)}</span><span>· ${when(p.created_at)}</span>${p.sample?'<span class="badge badge-gray">Example topic</span>':''}</div><h3>${esc(p.title)}</h3><p class="body">${esc(p.body)}</p><div class="poll-box"><div class="toprow"><span class="label">Community sentiment poll</span><span class="small muted">${sum} response${sum===1?'':'s'}</span></div><div class="poll-choices">${[['SUPPORT','Support'],['OPPOSE','Oppose'],['ABSTAIN','Abstain']].map(([v,txt])=>`<button class="${p.my_vote===v?'chosen':''}" data-action="vote" data-proposal="${esc(p.id)}" data-choice="${v}">${p.my_vote===v?icon('check',13):''}${txt} <strong>${p.poll_counts[v]}</strong></button>`).join('')}</div><div class="poll-note">${!c?.joined?'Join this community before participating. ':''}This is a nonbinding opinion poll, not a legal proxy vote.</div></div></article>`}
function discussions(){return `<div class="page-heading"><div><div class="eyebrow">Ideas, not trading signals</div><h1>Member discussions</h1><p>Ask better questions, share research, and discuss responsible shareholder engagement.</p></div><button class="btn btn-primary" data-action="new-proposal">${icon('plus')} Start discussion</button></div><div class="discussion-layout"><div>${state.proposals.map(discussionCard).join('')||'<div class="empty-state">No discussions yet.</div>'}</div><aside class="stack"><div class="card info-card"><div class="badge">${icon('shield',13)} Know your rights</div><h3 style="margin-top:14px">A community poll ≠ a shareholder vote.</h3><p>Votes here express an opinion. Only an authorized proxy process or shareholder meeting lets an eligible investor cast a real shareholder vote.</p></div><div class="card info-card"><div class="label">Healthy community</div><h3>Better together, independent by choice.</h3><p>Ask for evidence, disclose conflicts of interest, and never coordinate efforts to artificially move market prices.</p></div></aside></div>`}
function communityDetail(){const c=state.selected;if(!c){return '<p>Community not found.</p>'}const posts=state.proposals.filter(p=>p.community_slug===c.slug);return `<button class="text-link" data-action="nav" data-view="communities" style="margin-bottom:17px">${icon('back')} All communities</button><div class="community-hero"><div><div class="badge badge-cream">${categoryName(c.category)}${c.symbol?' · '+esc(c.symbol):''}</div><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><div class="community-details"><span>${icon('users',14)} ${c.members} prototype member${c.members===1?'':'s'}</span><span>${icon('shield',14)} Discussion only</span><span>${c.visibility==='PRIVATE'?'Private members-only':'Public community'}</span></div></div><div style="display:flex;gap:8px;flex-wrap:wrap">${c.owner?`<button class="btn btn-quiet" data-action="invite" data-slug="${esc(c.slug)}">${icon('users',16)} Invite friends</button>`:''}${c.owner?'<span class="badge">Group owner</span>':`<button class="btn ${c.joined?'btn-quiet':'btn-primary'}" data-action="${c.joined?'leave':'join'}" data-slug="${esc(c.slug)}">${icon(c.joined?'check':'plus',16)} ${c.joined?'Joined · leave':'Join community'}</button>`}</div></div><div class="notice" style="margin-bottom:18px">${icon('wallet')}<span><strong>Your group can model its growth.</strong> The fund lab shows how member recruitment and example contributions affect a hypothetical total. No actual assets or commitments are involved. <button class="text-link" data-action="open-fund-lab" data-slug="${esc(c.slug)}">Explore group fund lab ${icon('arrow',14)}</button></span></div><div class="two-column"><div><div class="section-bar"><div><h2 class="section-title">Community discussions</h2><p class="section-subtitle">Research and opinion. Nothing here executes a trade.</p></div>${c.joined?`<button class="btn btn-primary btn-mini" data-action="new-proposal" data-slug="${esc(c.slug)}">${icon('plus',14)} New discussion</button>`:''}</div><div class="card">${posts.map(proposalRow).join('')||'<div class="empty-state">No discussions yet. Start one.</div>'}</div></div><div class="card info-card"><div class="label">What membership means</div><h3>A seat at the table.</h3><p>Participate in research, education, and nonbinding opinions. The community has no pooled assets and no legal control over company shares.</p><div class="divider"></div><p>Future ownership products will need independent legal structures, eligibility checks, and regulated infrastructure.</p></div></div>`}
function watchlist(){return `<div class="page-heading"><div><div class="eyebrow">Your research list</div><h1>My watchlist</h1><p>Follow topics you're interested in researching. Not your brokerage portfolio.</p></div></div><div class="card card-pad"><div class="toprow" style="flex-wrap:wrap"><div><h2 class="section-title">Symbols you're following</h2><p class="section-subtitle">No live price feeds or account connections yet.</p></div><form id="watch-form" class="watch-add"><input id="symbol" name="symbol" maxlength="12" placeholder="e.g. TSLA" pattern="[A-Za-z][A-Za-z0-9.\-]*" required aria-label="Ticker symbol"/><button class="btn btn-primary" type="submit">${icon('plus',15)} Add</button></form></div><div class="divider"></div>${state.watches.length?`<div class="stack">${state.watches.map(s=>`<div class="watch-chip">${icon('chart')}<strong>${esc(s)}</strong><span class="badge badge-gray">Research only</span><div class="spacer"></div><button title="Remove ${esc(s)}" aria-label="Remove ${esc(s)}" data-action="watch-remove" data-symbol="${esc(s)}">×</button></div>`).join('')}</div>`:`<div class="empty-state">${icon('eye',30)}No saved symbols yet. Try adding TSLA or another stock ticker you want to research.</div>`}</div><div class="notice" style="margin-top:17px">${icon('info')}<span>These are user-entered symbols. They are not verified listings, holdings, recommendations, market prices, or trade instructions.</span></div>`}
const previews = {
 brokerage:{icon:'chart',name:'Invest in stocks',kind:'Stock trading preview',intro:'Explore how Joe could research a public company, understand the risks, and eventually place a trade through a regulated brokerage partner.',facts:['A share is a small piece of a public company.','Market prices fluctuate; buying can lose money.','An order preview is not a purchase.'], steps:['Select a listed company and read its filings.','Compare risks and choose a hypothetical investment amount.','Preview an order and learn what fees and execution would mean.'],sample:'Example: an imaginary $100 order in TSLA. No real shares, market price or portfolio balance are shown.'},
 housing:{icon:'building',name:'Own housing together',kind:'Housing project preview',intro:'Learn how communities might buy, finance, and govern an apartment building without promising returns or offering a security.',facts:['Buildings have maintenance, taxes, repairs and vacancy risk.','Residents, lenders, and investors can have different rights.','Affordable rents may limit financial returns.'],steps:['Research a property and local housing needs.','Compare a cooperative, community land trust, and investor-owned model.','Explore hypothetical acquisition budgets and transparent governance.'],sample:'Illustrative property budget: $1,000,000 purchase, $250,000 example equity, plus financing, closing costs and reserves. No actual property is offered.'},
 business:{icon:'store',name:'Own businesses together',kind:'Business acquisition preview',intro:'Discover how employees, neighbors or an investment entity might acquire a business and learn to analyze it.',facts:['Revenue is not the same as profit.','Business owners may sell equity or assets under different terms.','You must account for debt, taxes, payroll and working capital.'],steps:['Explore a fictional local business profile.','Review sample financial statements, debt and customer concentration.','Compare ownership rights, operating risks and an illustrative acquisition model.'],sample:'Fictional bakery acquisition: asking price $350,000. This is not an actual listing or investment offer.'},
 governance:{icon:'vote',name:'Shareholder voice',kind:'Shareholder rights preview',intro:'Understand how a group might discuss proposals and how eligible owners actually cast proxy votes through authorized channels.',facts:['Community opinion polls do not count as company votes.','Shareholder influence depends on voting rights, ownership and governing rules.','Some coordinated shareholder actions can trigger disclosures.'],steps:['Read the issuer’s proxy statement and agenda.','Discuss the choices and their potential consequences.','See the authorized broker voting process you would use separately.'],sample:'Example: a fictional community poll about board accountability. It does not submit or aggregate any actual proxy instructions.'}
};
function previewDetail(){const p=previews[state.featurePreview]||previews.brokerage;return `<button class="text-link" data-action="nav" data-view="ownership" style="margin-bottom:17px">${icon('back')} Back to ownership demos</button><div class="page-heading"><div><div class="eyebrow">Interactive product preview · No transactions</div><h1>${esc(p.name)}</h1><p>${esc(p.intro)}</p></div><span class="badge badge-cream">Demo only</span></div>${state.featurePreview==='brokerage'?`<div class="card card-pad" style="margin-bottom:17px"><div class="toprow" style="align-items:center;flex-wrap:wrap"><div><div class="label">Actual public company information</div><h2 class="section-title">Read an SEC filing</h2><p class="section-subtitle">Free, primary-source disclosures; not real-time stock prices.</p></div><div style="display:flex;flex-wrap:wrap;gap:8px"><select id="sec-ticker" aria-label="Company" class="form-input"><option value="TSLA" ${state.secSymbol==='TSLA'?'selected':''}>Tesla (TSLA)</option><option value="AAPL" ${state.secSymbol==='AAPL'?'selected':''}>Apple (AAPL)</option><option value="MSFT" ${state.secSymbol==='MSFT'?'selected':''}>Microsoft (MSFT)</option><option value="NVDA" ${state.secSymbol==='NVDA'?'selected':''}>NVIDIA (NVDA)</option><option value="AMZN" ${state.secSymbol==='AMZN'?'selected':''}>Amazon (AMZN)</option></select><button class="btn btn-primary" data-action="load-sec">Load company facts ${icon('arrow',14)}</button></div></div>${state.secData?`<div class="divider"></div><p class="small muted">${esc(state.secData.message)}</p>${state.secData.status==='ok'?`<div class="metric-grid" style="margin-top:14px">${Object.entries(state.secData.facts||{}).map(([key,v])=>metric(key.replace(/_/g,' '),currency(v.value),`${v.form} · period ending ${v.period_end}, filed ${v.filed}`,'book')).join('')}</div>`:''}<a class="text-link" target="_blank" rel="noopener noreferrer" href="${esc(state.secData.filing_page)}">Read official SEC filings ${icon('external',14)}</a>`:`<div class="notice">${icon('info')}<span>SEC data can be loaded here when a contact-identified feed is configured. We always identify reporting periods and link to original filings.</span></div>`}</div>`:''}<div class="hero-banner"><div class="eyebrow">${esc(p.kind)}</div><h2>See how it could work.</h2><p>${esc(p.sample)}</p></div><div class="two-column"><div class="card card-pad"><div class="label">A guided example</div><h2 class="section-title">Three simple steps</h2><div class="roadmap">${p.steps.map((step,i)=>`<div class="roadmap-item"><span class="round-num">${i+1}</span><p>${esc(step)}</p></div>`).join('')}</div><button class="btn btn-primary" data-action="nav" data-view="learn">Learn the basics ${icon('arrow')}</button></div><aside class="card info-card"><div class="label">Before you do anything</div><h3>What you need to know</h3>${p.facts.map(t=>`<p style="padding:9px 0">${icon('check',14)} ${esc(t)}</p>`).join('')}<div class="notice">These are educational examples, not live holdings, investment offers, or orders.</div></aside></div>`}
function ownership(){const areas=[['brokerage','chart',previews.brokerage],['housing','building',previews.housing],['business','store',previews.business],['governance','vote',previews.governance]];return `<div class="page-heading"><div><div class="eyebrow">Try the long-term vision safely</div><h1>Ownership experiences</h1><p>Explore the full product as educational previews, with no money exchanged.</p></div><span class="badge badge-cream">Simulations</span></div><div class="hero-banner" style="min-height:235px"><div class="eyebrow">One platform, more ways to own</div><h2>From a single share to a community-owned business.</h2><p>Every path is explained in plain English. Screens never pretend a demo is a real transaction.</p></div><div class="locked-grid">${areas.map(([key,ic,p])=>`<div class="card locked-feature"><div class="toprow"><div class="community-icon">${icon(ic,22)}</div><span class="badge badge-cream">Preview</span></div><h3>${esc(p.name)}</h3><p>${esc(p.intro)}</p><button class="text-link" data-action="feature-preview" data-feature="${key}">Explore walkthrough ${icon('arrow')}</button></div>`).join('')}</div><div class="notice" style="margin-top:18px">${icon('shield')}<span>All amounts and deal examples in these previews are fictional unless linked to a named source. No live stock prices, real estate offerings, buying, custody, fundraising or proxy submission.</span></div>`}

const currency = n => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
const fundTiers=[{amount:100000,name:'$100K community milestone',detail:'Research methods, meetings, clear rules and member protections.'},{amount:1000000,name:'$1M scale milestone',detail:'Serious governance, transparent records and independent reviews.'},{amount:10000000,name:'$10M scale milestone',detail:'Potential professional operations, oversight and compliance planning.'},{amount:100000000,name:'$100M institutional-scale illustration',detail:'AUM at this scale is not the same as ownership, approval or a hedge fund license.'}];
async function openFundLab(slug){const selectedSlug=slug || state.communities.find(x=>x.joined)?.slug || state.communities.find(x=>x.visibility==='PUBLIC')?.slug;
 if(!selectedSlug){state.view='communities';render();toast('Create or join a group first.',true);return;}
 const result=await api('/communities/'+encodeURIComponent(selectedSlug)+'/fund-lab');state.fundLab=result;state.fundCommunity=selectedSlug;state.view='fundlab';render();window.scrollTo({top:0,behavior:'instant'});
}
function fundBuilder(){const c=state.communities.find(x=>x.slug===state.fundCommunity);
 if(!state.fundLab){return `<div class="page-heading"><div><div class="eyebrow">A learning lab for group ownership</div><h1>Build an investment group</h1><p>Start as a research community, then explore what the path to a real regulated fund could require.</p></div></div><div class="card card-pad"><h3>Select a group to explore</h3><div class="stack" style="margin-top:12px">${state.communities.map(x=>`<button class="btn btn-quiet" data-action="open-fund-lab" data-slug="${esc(x.slug)}">${icon('users')} ${esc(x.name)} ${icon('arrow',14)}</button>`).join('')}</div><button style="margin-top:14px" class="btn btn-primary" data-action="create-group">${icon('plus')} Create my group</button></div>`}
 const p=state.fundLab.plan;const canEdit=state.fundLab.can_edit;
 return `<div class="page-heading"><div><div class="eyebrow">Group growth simulator · Not a real investment fund</div><h1>Build your collective.</h1><p>Model how a small community <strong>could</strong> grow, then learn what would be needed to create a real investment vehicle.</p></div><span class="badge badge-cream">Education only</span></div>
 <div class="card card-pad" style="margin-bottom:18px"><div class="toprow" style="align-items:center;flex-wrap:wrap"><div><div class="label">Your selected community</div><h2 class="section-title">${esc(c?.name||'Community')}</h2></div><select id="fund-group-select" class="form-input" style="max-width:250px" aria-label="Choose investment group">${state.communities.map(x=>`<option value="${esc(x.slug)}" ${x.slug===state.fundCommunity?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="notice" style="margin-top:13px">${icon('info')}<span>There is no legal fund, pooled brokerage account, investment commitment or actual assets under management (AUM). Group membership does not represent ownership of investments.</span></div></div>
 <div class="metric-grid">${metric('Actual group members',p.group_members,'Real platform membership count','users')}${metric('Simulated future members',p.hypothetical_members,'Based only on example recruitment','chart')}${metric('Hypothetical capital',currency(p.hypothetical_capital),'Example arithmetic, not invested or raised','wallet')}${metric('Money collected',currency(p.real_money_collected),'COMMON does not collect deposits','shield')}</div>
 <div class="two-column"><div class="card card-pad"><div class="label">Adjust the example</div><h2 class="section-title">What if your group grew?</h2><p class="section-subtitle">Try different numbers. For this exercise, every example member contributes once and market returns are zero. Nobody is asked to commit money.</p><form id="fund-lab-form" class="fund-form"><div class="field"><label for="fund-contrib">Example amount per member ($)</label><input class="form-input" type="number" min="0" max="1000000" step="1" value="${p.contribution_example}" name="contribution_example" id="fund-contrib" ${canEdit?'':'disabled'} required><small>Example only—not a pledge or deposit.</small></div><div class="field"><label for="fund-recruits">New example members each month</label><input class="form-input" type="number" min="0" max="10000" value="${p.new_members_example}" name="new_members_example" id="fund-recruits" ${canEdit?'':'disabled'} required></div><div class="field"><label for="fund-months">Months to simulate</label><input class="form-input" type="number" min="1" max="120" value="${p.months_example}" name="months_example" id="fund-months" ${canEdit?'':'disabled'} required></div>${canEdit?'<button class="btn btn-primary" type="submit">Save example scenario &rarr;</button>':'<div class="notice">Only the group creator can edit this shared teaching example. Members can inspect the assumptions.</div>'}</form><div class="notice" style="margin-top:16px">${icon('lightbulb')}<span>Example: ${p.hypothetical_members.toLocaleString()} people × ${currency(p.contribution_example)} = ${currency(p.hypothetical_capital)}. This is <strong>not a forecast</strong> or a record of commitments.</span></div></div>
 <aside class="stack"><div class="card info-card"><div class="label">Four potential stages</div><h3>From an idea to an institution</h3><div class="roadmap">${fundTiers.map(t=>`<div class="roadmap-item"><span class="round-num">${icon('target',13)}</span><div><strong>${t.name}</strong><p>${t.detail}</p><small class="muted">${p.hypothetical_capital>=t.amount?'Hypothetical amount reaches this example milestone':'Requires '+currency(Math.max(0,t.amount-p.hypothetical_capital))+' more hypothetical capital'}</small></div></div>`).join('')}</div><div class="notice">These dollar levels are learning milestones, not legal thresholds or guarantees of hedge fund or private equity status.</div></div></aside></div>
 <div class="card card-pad" style="margin-top:18px"><div class="label">What changes when money becomes real?</div><h2 class="section-title">A group isn't automatically a fund</h2><div class="roadmap"><div class="roadmap-item"><span class="round-num">1</span><div><strong>Research community</strong><p>People meet, investigate opportunities, and make their own decisions. This is what COMMON enables today.</p></div></div><div class="roadmap-item"><span class="round-num">2</span><div><strong>Legally structured investment club</strong><p>Some active-member clubs may pool capital under a suitable structure, but passive members and fees can change regulatory obligations.</p></div></div><div class="roadmap-item"><span class="round-num">3</span><div><strong>Professional investment vehicle</strong><p>A hedge fund typically invests in financial assets; a private equity fund typically buys ownership interests in private businesses. Each requires legal, compliance, tax and operational design. Private funds often have investor eligibility restrictions.</p></div></div><div class="roadmap-item"><span class="round-num">4</span><div><strong>Scale responsibly</strong><p>More members do not erase investor eligibility, custody, adviser rules or beneficial-ownership reporting. Growth requires independent oversight, not just a bigger balance on a screen.</p></div></div></div><p class="small muted">Source: <a href="https://www.sec.gov/files/investor/pubs/invclub.htm" target="_blank" rel="noopener noreferrer">SEC investment-club bulletin</a> · <a href="https://www.sec.gov/resources-small-businesses/capital-raising-building-blocks/private-funds" target="_blank" rel="noopener noreferrer">SEC private funds guide</a></p></div>`}

const lessons=[
 ['Stock ownership vs. stock price','Owning a share usually means holding a small ownership interest in a company. The market price can change dramatically and may not reflect short-term business performance.','Understand ordinary shares, market prices, dilution, and why ownership comes with risk.'],
 ['What does a shareholder vote do?','Shareholders may vote on board elections and other matters according to company rules and security rights. Community opinion polls are not proxy votes.','Understand record dates, broker-held shares, proxy statements, and the practical limits of a small position.'],
 ['Risk, diversification and fees','Concentrating money in one company can produce large losses. Diversification spreads exposure, while fees can compound over many years.','Compare scenarios using your own goals and learn why past results do not guarantee future returns.'],
 ['What is an investment club?','A self-directed club may research together while members invest separately. Other clubs pool money and can face securities, adviser, and entity requirements.','Understand why a chat group is not automatically a legal fund or licensed adviser.'],
 ['How can a neighborhood own housing?','Land trusts and cooperative structures can give residents long-term stewardship and sometimes preserve affordability. They require real governance and financing.','Explore who owns the land, who owns the buildings, and who has voting rights.'],
 ['Research before you act','Company filings, incentives, business economics and conflicting sources can matter more than hot tips. Claims should be backed by evidence.','Practice checking SEC filings, cash flow, governance materials, and conflicts of interest.'],
   ['What is AUM?','AUM means assets under management. It is the actual value of assets managed by an investment manager—not a community membership count, a hypothetical calculator total or a plan to raise funds.','Learn why our Fund Lab simulated dollars are never labeled real AUM and why investment returns can be negative.'],
   ['Hedge fund vs. private equity','A hedge fund often trades financial instruments using a defined strategy. Private equity funds generally buy stakes in businesses and may hold them for years. Both involve legal structures, eligible investors and significant responsibilities.','Learn how an investment club differs from managing other people’s money and why accreditation and adviser rules may apply.'],
];
function learning(){if(state.lesson!==null){const l=lessons[state.lesson];return `<button class="text-link" data-action="lesson-back" style="margin-bottom:22px">${icon('back')} All lessons</button><div class="card lesson-detail"><div class="badge">Lesson ${state.lesson+1} of ${lessons.length}</div><h1 style="margin-top:17px;font-size:29px;letter-spacing:-.8px">${l[0]}</h1><p>${l[1]}</p><div class="divider"></div><div class="label">What to understand</div><p>${l[2]}</p><div class="notice">${icon('info')}<span>Educational overview, not individualized investment advice. Ask questions and verify original sources before acting.</span></div><button class="btn btn-primary" style="margin-top:25px" data-action="lesson-back">${icon('check')} Complete reading</button></div>`}
return `<div class="page-heading"><div><div class="eyebrow">No finance degree required</div><h1>The ownership academy</h1><p>Everything Joe the plumber needs to understand financial ownership—explained clearly.</p></div></div><div class="learning-grid">${lessons.map((l,i)=>`<article class="card lesson-card"><div class="toprow"><div class="community-icon">${icon(i===4?'building':i===1?'vote':i===3?'users':i===2?'shield':'book',21)}</div><span class="n">LESSON ${String(i+1).padStart(2,'0')}</span></div><h3>${l[0]}</h3><p>${l[1]}</p><button class="text-link" data-action="lesson" data-index="${i}">Explore lesson ${icon('arrow')}</button></article>`).join('')}</div>`}
function render(){if(!state.user){app.innerHTML=authScreen();return}let content;switch(state.view){case 'overview':content=overview();break;case 'communities':content=communityList();break;case 'community':content=communityDetail();break;case 'discussions':content=discussions();break;case 'watchlist':content=watchlist();break;case 'ownership':content=ownership();break;case 'preview':content=previewDetail();break;case 'fundlab':content=fundBuilder();break;case 'learn':content=learning();break;default:content=overview()}app.innerHTML=shell(content);if(state.modal)openModal()}
function modalHTML(){
 if(state.modal?.type==='invite'){const link=state.modal.link;return `<div class="modal-backdrop" data-action="modal-close-back"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><div class="eyebrow">Invite your people</div><h2 id="modal-title">Your group invitation</h2></div><button class="close" data-action="modal-close" aria-label="Close">×</button></div><p class="small muted">This link can be used by up to 50 people in the next 30 days. It only grants access to the discussion community—never financial accounts or assets.</p><div class="field"><label for="invite-link">Invitation link</label><input readonly id="invite-link" class="form-input" value="${esc(link)}" /></div><button class="btn btn-primary" data-action="copy-invite" style="margin-top:20px;width:100%">Copy invitation link ${icon('arrow')}</button></div></div>`}
 if(state.modal?.type==='community'){return `<div class="modal-backdrop" data-action="modal-close-back"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><div class="eyebrow">Organize with friends</div><h2 id="modal-title">Create your community</h2><p class="muted small" style="margin-top:7px">Research together, make investment decisions independently.</p></div><button type="button" class="close" aria-label="Close" data-action="modal-close">×</button></div><form id="community-form"><div class="field"><label for="group-name">Group name</label><input class="form-input" id="group-name" name="name" minlength="4" maxlength="80" placeholder="e.g. Joe's Ownership Club" required /></div><div class="field"><label for="group-description">What will you research?</label><textarea class="form-input" id="group-description" name="description" minlength="30" maxlength="600" style="min-height:100px" placeholder="Describe the research goals and community rules..." required></textarea></div><div class="field"><label for="group-category">Focus</label><select class="form-input" id="group-category" name="category"><option value="PUBLIC_EQUITY">Public companies and shareholder rights</option><option value="HOUSING">Community housing ownership</option><option value="BUSINESS">Local business ownership</option></select></div><div class="field"><label for="group-visibility">Who can access?</label><select class="form-input" id="group-visibility" name="visibility"><option value="PRIVATE">Private — invitation only</option><option value="PUBLIC">Public — anyone can join</option></select></div><div class="notice" style="margin-top:17px">${icon('shield')}<span>Creating a group does not form a legal investment club, pool capital, issue securities, or submit orders.</span></div><button class="btn btn-primary" type="submit" style="margin-top:16px;width:100%">Create research group ${icon('arrow')}</button></form></div></div>`}
 const inCommunity=state.selected?.slug;const opts=state.communities.filter(c=>c.joined);return `<div class="modal-backdrop" data-action="modal-close-back"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><div class="eyebrow">Share your research</div><h2 id="modal-title">Start a discussion</h2><p class="muted small" style="margin-top:7px">Clear claims, visible evidence, thoughtful discussion.</p></div><button type="button" class="close" aria-label="Close" data-action="modal-close">×</button></div><form id="proposal-form"><div class="field"><label for="proposal-community">Community</label><select name="community" id="proposal-community" class="form-input" required>${opts.map(c=>`<option value="${esc(c.slug)}" ${c.slug===(state.modal.slug||inCommunity)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="proposal-topic">Topic</label><select name="topic" id="proposal-topic" class="form-input"><option value="RESEARCH">Company research</option><option value="EDUCATION">Financial education</option><option value="GOVERNANCE">Shareholder governance</option><option value="OWNERSHIP">Collective ownership</option></select></div><div class="field"><label for="proposal-title">Discussion title</label><input class="form-input" name="title" id="proposal-title" minlength="12" maxlength="160" placeholder="A specific question to investigate" required/></div><div class="field"><label for="proposal-body">Context and evidence</label><textarea class="form-input" name="body" id="proposal-body" minlength="40" maxlength="4000" placeholder="Explain the question, cite sources where possible, and describe important risks..." required></textarea></div><div class="notice">${icon('info')}<span>This creates a nonbinding discussion. It does not solicit a stock purchase, cast a shareholder vote, or create an investment vehicle.</span></div><button class="btn btn-primary" type="submit" style="width:100%">Publish discussion ${icon('arrow')}</button></form></div></div>`}
function openModal(){document.getElementById('modal-container')?.remove();const div=document.createElement('div');div.id='modal-container';div.innerHTML=modalHTML();document.body.appendChild(div);setTimeout(()=>div.querySelector('input,select')?.focus(),0)}
function closeModal(){state.modal=null;document.getElementById('modal-container')?.remove()}
async function navigate(view){state.view=view;state.selected=null;state.lesson=null;render();window.scrollTo({top:0,behavior:'instant'})}
async function openCommunity(slug){const data=await api('/communities/'+encodeURIComponent(slug));state.selected=data.community;state.view='community';render();window.scrollTo({top:0,behavior:'instant'})}

app.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{
  if(action==='auth-mode'){state.authMode=b.dataset.mode;render();return}
  if(action==='demo'){b.disabled=true;b.textContent='Opening demo…';const result=await api('/auth/demo',{method:'POST'});state.user=result.user;await loadData();state.view='overview';await applyPendingInvite();render();return}
  if(action==='nav'){if(b.dataset.view==='fundlab'){await openFundLab();return}await navigate(b.dataset.view);return}
  if(action==='category'){state.category=b.dataset.category;render();return}
  if(action==='open-community'){await openCommunity(b.dataset.slug);return}
  if(action==='open-fund-lab'){await openFundLab(b.dataset.slug);return}
  if(action==='feature-preview'){state.featurePreview=b.dataset.feature;state.view='preview';render();return}
  if(action==='load-sec'){state.secData=await api('/research/companies/'+state.secSymbol);render();return}
  if(action==='open-discussions'){await navigate('discussions');return}
  if(action==='join'||action==='leave'){await api(`/communities/${encodeURIComponent(b.dataset.slug)}/${action}`,{method:'POST'});await loadData();await openCommunity(b.dataset.slug);toast(action==='join'?'You joined the discussion community.':'You left the discussion community.');return}
  if(action==='create-group'){state.modal={type:'community'};openModal();return}
  if(action==='invite'){toast('Shared invitations require a live backend. This showcase is local to your browser.',true);return}
  if(action==='new-proposal'){const slug=b.dataset.slug;const joined=state.communities.filter(c=>c.joined);if(!joined.length){toast('Join a community before opening a discussion.',true);return}state.modal={type:'proposal',slug};openModal();return}
  if(action==='vote'){const id=b.dataset.proposal;const p=state.proposals.find(x=>x.id===id);const c=state.communities.find(x=>x.slug===p?.community_slug);if(!c?.joined){toast('Join '+c?.name+' before participating.',true);return}const result=await api(`/proposals/${encodeURIComponent(id)}/vote`,{method:'POST',body:JSON.stringify({choice:b.dataset.choice})});state.proposals=state.proposals.map(p=>p.id===id?result.proposal:p);render();toast('Community opinion saved. This is not a proxy vote.');return}
  if(action==='watch-remove'){await api('/watchlist/'+encodeURIComponent(b.dataset.symbol),{method:'DELETE'});state.watches=state.watches.filter(v=>v!==b.dataset.symbol);render();toast('Removed from your research list.');return}
  if(action==='lesson'){state.lesson=Number(b.dataset.index);render();return}
  if(action==='lesson-back'){state.lesson=null;render();return}
  if(action==='logout'){await api('/auth/logout',{method:'POST'});state.user=null;state.view='overview';state.selected=null;render();return}
}catch(err){toast(err.message,true);if(action==='demo'){b.disabled=false;b.textContent='Explore interactive demo as Joe'}}});

app.addEventListener('submit',async e=>{if(e.target.id!=='auth-form'&&e.target.id!=='watch-form')return;e.preventDefault();const f=e.target;const d=new FormData(f);const submit=f.querySelector('button[type="submit"]');submit.disabled=true;try{
  if(f.id==='auth-form'){const endpoint=state.authMode==='register'?'register':'login';const body={email:d.get('email'),password:d.get('password')};if(endpoint==='register')body.name=d.get('name');const res=await api('/auth/'+endpoint,{method:'POST',body:JSON.stringify(body)});state.user=res.user;await loadData();state.view='overview';await applyPendingInvite();render();toast('Welcome to COMMON!');return}
  if(f.id==='watch-form'){const symbol=String(d.get('symbol')).trim().toUpperCase();await api('/watchlist',{method:'POST',body:JSON.stringify({symbol})});state.watches=[...new Set([...state.watches,symbol])].sort();render();toast(symbol+' saved for research.');return}
}catch(err){toast(err.message,true)}finally{submit.disabled=false}});

document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]');if(!a)return;if(a.dataset.action==='modal-close'||(a.dataset.action==='modal-close-back'&&e.target===a))closeModal();if(a.dataset.action==='copy-invite'){const input=document.getElementById('invite-link');try{await navigator.clipboard.writeText(input.value);toast('Invitation link copied.')}catch{input.select();toast('Select the link and copy it to share.')}}});
document.addEventListener('submit',async e=>{if(!['proposal-form','community-form'].includes(e.target.id))return;e.preventDefault();const form=e.target;const d=new FormData(form);const submit=form.querySelector('button[type="submit"]');submit.disabled=true;try{
 if(form.id==='community-form'){const result=await api('/communities',{method:'POST',body:JSON.stringify({name:d.get('name'),description:d.get('description'),category:d.get('category'),visibility:d.get('visibility')})});closeModal();await loadData();await openCommunity(result.community.slug);toast('Community created. Invite your friends!');return}
 const slug=d.get('community');await api('/communities/'+encodeURIComponent(slug)+'/proposals',{method:'POST',body:JSON.stringify({title:d.get('title'),body:d.get('body'),topic:d.get('topic')})});closeModal();await loadData();state.view='discussions';render();toast('Discussion published successfully.')}catch(err){toast(err.message,true);submit.disabled=false}});
document.addEventListener('change',async e=>{if(e.target.id==='sec-ticker'){state.secSymbol=e.target.value;state.secData=null;return;}if(e.target.id==='fund-group-select'){try{await openFundLab(e.target.value)}catch(err){toast(err.message,true)}}});
document.addEventListener('submit',async e=>{if(e.target.id!=='fund-lab-form')return;e.preventDefault();const f=e.target;const d=new FormData(f);const btn=f.querySelector('button[type=submit]');if(btn)btn.disabled=true;try{const payload={contribution_example:Number(d.get('contribution_example')),new_members_example:Number(d.get('new_members_example')),months_example:Number(d.get('months_example'))};state.fundLab=await api('/communities/'+encodeURIComponent(state.fundCommunity)+'/fund-lab',{method:'PUT',body:JSON.stringify(payload)});render();toast('The hypothetical growth scenario was saved. No money has moved.')}catch(err){toast(err.message,true);if(btn)btn.disabled=false}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.modal)closeModal()});
initialize();
